/** Shared visual strokes for editor routes, previews, legends, and SVG export. */
const strokeStyles = new Set(['solid', 'dashed', 'dotted', 'double', 'triple', 'outlined']);
const strokeNumber = value => String(Number(value.toFixed(3)));
const strokeColor = (value, fallback) => typeof value === 'string' && /^#[0-9a-f]{3}(?:[0-9a-f]{3})?$/i.test(value) ? value : fallback;
const strokeWidth = line => Number.isFinite(line?.width) ? Math.max(4, Math.min(24, line.width)) : 8;
const strokeJoin = line => line?.cornerRadius === 0 || line?.cornerStyle === 'sharp' ? 'miter' : line?.cornerStyle === 'bevel' ? 'bevel' : 'round';

/** Radius around a route centerline occupied by its visible strokes. */
export function lineStrokeExtent(line = {}) {
  const width = strokeWidth(line);
  // A miter limit of 2 bounds acute vertices to one full stroke width.
  return (strokeJoin(line) === 'miter' ? width : width / 2) + (line.style === 'outlined' ? 2 : 0);
}

/** Render a visual route only. Hit targets are supplied by the editor. */
export function renderLineStroke(pathD, line = {}, options = {}) {
  const style = strokeStyles.has(line.style) ? line.style : 'solid';
  const width = strokeWidth(line);
  const color = strokeColor(options.color, strokeColor(line.color, '#4068E8'));
  const paper = strokeColor(options.paper, '#f8f9f5');
  const join = strokeJoin(line);
  // Paths are generated by our geometry module. Reject foreign markup if a
  // caller supplies arbitrary text instead of allowing it into SVG attributes.
  const path = typeof pathD === 'string' && /^[MmLlHhVvCcSsQqTtAaZz0-9eE+.,\s-]*$/.test(pathD) ? pathD : '';
  const layer = (ink, weight, extra = '') => `<path class="route-path" d="${path}" fill="none" stroke="${ink}" stroke-width="${strokeNumber(weight)}" stroke-linecap="round" stroke-linejoin="${join}" stroke-miterlimit="2" style="stroke-linejoin:${join};stroke-linecap:round"${extra}/>`;
  let markup;
  switch (style) {
    case 'dashed': markup = layer(color, width, ' stroke-dasharray="6 10"'); break;
    case 'dotted': markup = layer(color, width, ` stroke-dasharray="0 ${strokeNumber(width * 1.8)}"`); break;
    case 'double': markup = layer(color, width) + layer(paper, width * .35); break;
    case 'triple': markup = layer(color, width) + layer(paper, width * .6) + layer(color, width * .2); break;
    case 'outlined': markup = layer(paper, width + 4) + layer(color, width); break;
    default: markup = layer(color, width);
  }
  return `<g class="route-strokes" data-line-style="${style}" pointer-events="none">${markup}</g>`;
}
